function isValidSubdomain(subdomain) {
  // Check for valid DNS subdomain format (letters, numbers, hyphens, and dots)
  if (!/^[a-zA-Z0-9\-\.]+$/.test(subdomain)) {
    return false;
  }

  // Check if the subdomain is not empty and does not contain invalid sequences like '..'
  if (subdomain.includes('..') || subdomain.startsWith('.') || subdomain.endsWith('.')) {
    return false;
  }

  return true;
}

// Example usage
console.log(isValidSubdomain('subdomain'));      // true
console.log(isValidSubdomain('a.b'));            // true
console.log(isValidSubdomain('invalid..sub'));   // false
console.log(isValidSubdomain('invalid.sub.'));   // false
console.log(isValidSubdomain('invalid..sub'));   // false

